-- ============================================================
-- Retail Sales Analytics Database — Schema
-- Engine: MySQL 8.0+ (also SQLite-compatible for the demo build)
-- ============================================================

DROP TABLE IF EXISTS order_items;
DROP TABLE IF EXISTS orders;
DROP TABLE IF EXISTS products;
DROP TABLE IF EXISTS categories;
DROP TABLE IF EXISTS customers;
DROP TABLE IF EXISTS employees;
DROP TABLE IF EXISTS stores;

-- ------------------------------------------------------------
-- Stores & Employees (self-referencing manager relationship)
-- ------------------------------------------------------------
CREATE TABLE stores (
    store_id      INTEGER PRIMARY KEY AUTOINCREMENT,
    store_name    VARCHAR(100) NOT NULL,
    city          VARCHAR(60)  NOT NULL,
    state         VARCHAR(60)  NOT NULL,
    opened_date   DATE
);

CREATE TABLE employees (
    employee_id   INTEGER PRIMARY KEY AUTOINCREMENT,
    first_name    VARCHAR(50)  NOT NULL,
    last_name     VARCHAR(50)  NOT NULL,
    store_id      INTEGER      NOT NULL,
    manager_id    INTEGER,                       -- self-referencing FK
    hire_date     DATE NOT NULL,
    role          VARCHAR(40)  NOT NULL,
    FOREIGN KEY (store_id)   REFERENCES stores(store_id),
    FOREIGN KEY (manager_id) REFERENCES employees(employee_id)
);

-- ------------------------------------------------------------
-- Customers
-- ------------------------------------------------------------
CREATE TABLE customers (
    customer_id     INTEGER PRIMARY KEY AUTOINCREMENT,
    first_name      VARCHAR(50) NOT NULL,
    last_name       VARCHAR(50) NOT NULL,
    email           VARCHAR(120) UNIQUE NOT NULL,
    city            VARCHAR(60),
    state           VARCHAR(60),
    signup_date     DATE NOT NULL,
    customer_segment VARCHAR(20) DEFAULT 'Standard' CHECK (customer_segment IN ('Standard','Premium','VIP'))
);

-- ------------------------------------------------------------
-- Categories & Products
-- ------------------------------------------------------------
CREATE TABLE categories (
    category_id    INTEGER PRIMARY KEY AUTOINCREMENT,
    category_name  VARCHAR(60) NOT NULL UNIQUE
);

CREATE TABLE products (
    product_id     INTEGER PRIMARY KEY AUTOINCREMENT,
    product_name   VARCHAR(120) NOT NULL,
    category_id    INTEGER NOT NULL,
    unit_price     DECIMAL(10,2) NOT NULL CHECK (unit_price >= 0),
    unit_cost      DECIMAL(10,2) NOT NULL CHECK (unit_cost >= 0),
    FOREIGN KEY (category_id) REFERENCES categories(category_id)
);

-- ------------------------------------------------------------
-- Orders & Order Items (many-to-many bridge: orders <-> products)
-- ------------------------------------------------------------
CREATE TABLE orders (
    order_id       INTEGER PRIMARY KEY AUTOINCREMENT,
    customer_id    INTEGER NOT NULL,
    store_id       INTEGER NOT NULL,
    employee_id    INTEGER,
    order_date     DATE NOT NULL,
    order_status   VARCHAR(20) DEFAULT 'Completed' CHECK (order_status IN ('Completed','Cancelled','Returned')),
    FOREIGN KEY (customer_id) REFERENCES customers(customer_id),
    FOREIGN KEY (store_id)    REFERENCES stores(store_id),
    FOREIGN KEY (employee_id) REFERENCES employees(employee_id)
);

CREATE TABLE order_items (
    order_item_id  INTEGER PRIMARY KEY AUTOINCREMENT,
    order_id       INTEGER NOT NULL,
    product_id     INTEGER NOT NULL,
    quantity       INTEGER NOT NULL CHECK (quantity > 0),
    unit_price     DECIMAL(10,2) NOT NULL,   -- price captured at time of sale
    FOREIGN KEY (order_id)   REFERENCES orders(order_id),
    FOREIGN KEY (product_id) REFERENCES products(product_id)
);

-- ------------------------------------------------------------
-- Helpful indexes for analytical queries
-- ------------------------------------------------------------
CREATE INDEX idx_orders_date       ON orders(order_date);
CREATE INDEX idx_orders_customer   ON orders(customer_id);
CREATE INDEX idx_order_items_order ON order_items(order_id);
CREATE INDEX idx_order_items_prod  ON order_items(product_id);


